import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.CzVS_xMp.js";const p=JSON.parse('{"title":"Stanford CS149 / Parallel Computing","description":"","frontmatter":{},"headers":[],"relativePath":"gpu/cs149/index.md","filePath":"gpu/cs149/index.md","lastUpdated":1788490169000}'),l={name:"gpu/cs149/index.md"};function o(s,e,n,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="stanford-cs149-parallel-computing" tabindex="-1">Stanford CS149 / Parallel Computing <a class="header-anchor" href="#stanford-cs149-parallel-computing" aria-label="Permalink to &quot;Stanford CS149 / Parallel Computing&quot;">​</a></h1><p>Stanford CS149 is the systems foundation course for this GPU track. It connects GPU programming with the broader parallel-computing model: multi-core CPUs, SIMD, scheduling, locality, synchronization, memory models, distributed data-parallel systems, DSLs, and hardware specialization.</p><p>Use this course to understand why GPU kernels, DNN execution, and accelerator systems behave the way they do beyond CUDA syntax alone.</p><h2 id="primary-resources" tabindex="-1">Primary Resources <a class="header-anchor" href="#primary-resources" aria-label="Permalink to &quot;Primary Resources&quot;">​</a></h2><ul><li><a href="https://gfxcourses.stanford.edu/cs149/fall23" target="_blank" rel="noreferrer">CS149 Fall 2023 course page</a></li><li><a href="https://www.youtube.com/playlist?list=PLoROMvodv4rMp7MTFr4hQsDEcX7Bx6Odp" target="_blank" rel="noreferrer">CS149 Fall 2023 YouTube playlist</a></li></ul><h2 id="study-priority" tabindex="-1">Study Priority <a class="header-anchor" href="#study-priority" aria-label="Permalink to &quot;Study Priority&quot;">​</a></h2><p>Focus first on:</p><ol><li>Parallelism, efficiency, and hardware utilization</li><li>Multi-core, SIMD, and multi-threading execution models</li><li>Work distribution, scheduling, locality, and contention</li><li>GPU architecture and CUDA programming abstractions</li><li>Data-parallel operations such as map, reduce, scan, and groupByKey</li><li>DNN execution on GPUs, including convolution, transformers, and fusion</li><li>Cache coherence, memory consistency, and synchronization</li><li>Domain-specific languages and hardware specialization</li></ol><h2 id="gpu-systems-lens" tabindex="-1">GPU Systems Lens <a class="header-anchor" href="#gpu-systems-lens" aria-label="Permalink to &quot;GPU Systems Lens&quot;">​</a></h2><p>For this repository, read CS149 with these questions in mind:</p><ul><li>How do CPU parallelism, SIMD, and GPU parallelism differ in their bottlenecks?</li><li>When does scheduling overhead dominate useful work?</li><li>How do locality and communication shape kernel and system performance?</li><li>Why do reductions, scans, and data movement show up repeatedly in ML systems?</li><li>Which memory model or synchronization assumption can make a parallel program incorrect?</li><li>How do DNN execution patterns map onto general parallel-computing principles?</li></ul><h2 id="lecture-notes" tabindex="-1">Lecture Notes <a class="header-anchor" href="#lecture-notes" aria-label="Permalink to &quot;Lecture Notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lecture</th><th>Topic</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Why Parallelism? Why Efficiency?</td><td>[lec01](lec01/</td></tr><tr><td>2</td><td>A Modern Multi-Core Processor</td><td>[lec02](lec02/</td></tr><tr><td>3</td><td>Multi-Core Architecture, Part II and ISPC</td><td>[lec03](lec03/</td></tr><tr><td>4</td><td>Parallel Programming Basics</td><td>[lec04](lec04/</td></tr></tbody></table>',13)])])}const m=t(l,[["render",o]]);export{p as __pageData,m as default};
